// =============================================================================
// Generic Webhook Tests
// =============================================================================

test.describe("Webhook Error Handling", () => {
  test("malformed JSON returns 400", async ({ request }) => {
    // Test against your primary webhook endpoint
    const response = await request.post(`${API_BASE}/api/webhooks/stripe`, {
      headers: { "Content-Type": "application/json" },
      data: "not valid json {{{",
    });

    expect(response.status()).toBe(400);
  });

  test("unknown webhook endpoint returns 404", async ({ request }) => {
    const response = await request.post(`${API_BASE}/api/webhooks/unknown-service`);
    expect(response.status()).toBe(404);
  });
});

